// ─────────────────────────────────────────────────────────────────────────────
// Node:  Transform Repos
// Type:  Code (JavaScript) — Mode: "Run Once for All Items"
// Input: ONE item from "Search GitHub Repos" → { total_count, incomplete_results, items: [...] }
// Output: ONE item → { generatedAt, topic, totalCount, topRepos: [5 cleaned repos], topRepo }
// Errors: throws a descriptive Error; the node's "On Error → Continue (using error output)"
//         setting routes it to the "Format Error" branch instead of failing silently.
// ─────────────────────────────────────────────────────────────────────────────

const TOP_N = 5;          // how many repositories to keep
const DESC_MAX = 200;     // max description length stored per repository
const TOPIC = 'artificial-intelligence'; // keep in sync with the `q` parameter of "Search GitHub Repos"

// ── 1. Validate the API response ─────────────────────────────────────────────
const first = $input.first();
const response = first ? first.json : null;

if (!response || typeof response !== 'object') {
  throw new Error('Transform Repos received no data from "Search GitHub Repos".');
}
if (!Array.isArray(response.items)) {
  throw new Error(
    'GitHub search response has no "items" array. Received keys: [' +
      Object.keys(response).join(', ') +
      ']. GitHub message: ' + (response.message || 'n/a')
  );
}
if (response.items.length === 0) {
  throw new Error(
    'GitHub search returned 0 repositories for topic "' + TOPIC + '". ' +
      'Check the `q` query parameter on "Search GitHub Repos".'
  );
}

// ── 2. Helpers ───────────────────────────────────────────────────────────────
const cleanText = (value, max) => {
  if (value === null || value === undefined) return '';
  let text = String(value)
    .replace(/[\u0000-\u001F\u007F]+/g, ' ') // strip control chars / newlines
    .replace(/\s+/g, ' ')                     // collapse whitespace
    .trim();
  if (max && text.length > max) {
    text = text.slice(0, max - 1).trimEnd() + '…';
  }
  return text;
};

// ── 3. Clean + normalise each repository ─────────────────────────────────────
const repos = response.items
  .filter((r) => r && r.full_name && r.html_url) // drop malformed entries
  .map((r) => ({
    name: r.name,
    fullName: r.full_name,
    owner: r.owner && r.owner.login ? r.owner.login : String(r.full_name).split('/')[0],
    repo: r.name || String(r.full_name).split('/')[1],
    description: cleanText(r.description, DESC_MAX) || 'No description provided',
    stars: Number.isFinite(Number(r.stargazers_count)) ? Number(r.stargazers_count) : 0,
    language: r.language || 'Not specified',
    url: r.html_url,
    lastPush: r.pushed_at || null,
  }));

if (repos.length === 0) {
  throw new Error('All repositories in the GitHub response were malformed (missing full_name / html_url).');
}

// ── 4. Sort by stars (desc, stable tie-break on name) and keep the top N ─────
repos.sort((a, b) => b.stars - a.stars || a.fullName.localeCompare(b.fullName));

const topRepos = repos.slice(0, TOP_N).map((r, i) => ({ rank: i + 1, ...r }));

// ── 5. Output a single item (keeps the rest of the flow linear) ──────────────
return [
  {
    json: {
      generatedAt: new Date().toISOString(),
      topic: TOPIC,
      totalCount: typeof response.total_count === 'number' ? response.total_count : null,
      topRepos,
      topRepo: topRepos[0], // highest-ranked → used by "Fetch README" and the IF node
    },
  },
];

// ─────────────────────────────────────────────────────────────────────────────
// Node:  Build Digest
// Type:  Code (JavaScript) — Mode: "Run Once for All Items"
// Input: ONE item from "Fetch README". That node uses "Include Response Headers and
//        Status" + "Never Error", so the item looks like:
//          { statusCode: 200, body: { content: '<base64>', encoding: 'base64', ... } }
//        or, for a missing README: { statusCode: 404, body: { message: 'Not Found' } }
//        or, for a network failure (Continue On Fail): { error: ... }
// Output: ONE item → { topRepo, topRepos, readme: {...}, telegramText, ... }
// The repository data itself is read from "Transform Repos" because the README
// response replaces the item's JSON.
// ─────────────────────────────────────────────────────────────────────────────

const TELEGRAM_LIMIT = 4000;   // Telegram's hard limit is 4096 characters
const README_SUMMARY_MAX = 350;

const data = $('Transform Repos').first().json;
const res = $input.first() ? $input.first().json || {} : {};

// ── 1. Work out what happened with the README request ────────────────────────
const readme = { available: false, status: 'unknown', httpStatus: null, summary: '', note: '' };

const errorToText = (e) => {
  if (!e) return 'unknown error';
  if (typeof e === 'string') return e;
  return e.message || e.description || JSON.stringify(e).slice(0, 200);
};

const decodeContent = (body) => {
  if (!body || typeof body.content !== 'string') return null;
  if (body.encoding === 'base64') {
    return Buffer.from(body.content, 'base64').toString('utf-8');
  }
  return body.content;
};

try {
  if (res.error) {
    // Network error / timeout after retries (Continue On Fail output)
    readme.status = 'request_failed';
    readme.note = 'README request failed: ' + errorToText(res.error);
  } else if (res.statusCode !== undefined) {
    readme.httpStatus = res.statusCode;
    if (res.statusCode === 200) {
      const markdown = decodeContent(res.body);
      if (markdown && markdown.trim()) {
        readme.available = true;
        readme.status = 'ok';
        readme.summary = summarizeMarkdown(markdown, README_SUMMARY_MAX);
        if (!readme.summary) {
          readme.note = 'README exists but no readable text could be extracted.';
        }
      } else {
        readme.status = 'empty';
        readme.note = 'README exists but is empty.';
      }
    } else if (res.statusCode === 404) {
      readme.status = 'not_found';
      readme.note = 'This repository has no README file.';
    } else if (res.statusCode === 403 || res.statusCode === 429) {
      readme.status = 'rate_limited';
      readme.note = 'README unavailable: GitHub API rate limit or access restriction (HTTP ' + res.statusCode + ').';
    } else {
      readme.status = 'http_error';
      readme.note = 'README unavailable: GitHub returned HTTP ' + res.statusCode + '.';
    }
  } else if (typeof res.content === 'string') {
    // Defensive: response format without fullResponse
    const markdown = decodeContent(res);
    readme.available = !!markdown;
    readme.status = markdown ? 'ok' : 'empty';
    readme.summary = markdown ? summarizeMarkdown(markdown, README_SUMMARY_MAX) : '';
  } else {
    readme.status = 'unexpected_response';
    readme.note = 'README response had an unexpected shape.';
  }
} catch (err) {
  readme.available = false;
  readme.status = 'parse_error';
  readme.note = 'README could not be processed: ' + err.message;
}

// ── 2. Markdown → short plain-text summary ───────────────────────────────────
function summarizeMarkdown(md, maxLen) {
  let t = String(md).replace(/\r\n/g, '\n');
  t = t
    .replace(/<!--[\s\S]*?-->/g, ' ')            // HTML comments
    .replace(/```[\s\S]*?```/g, ' ')              // fenced code blocks
    .replace(/~~~[\s\S]*?~~~/g, ' ')
    .replace(/<[^>]+>/g, ' ')                     // raw HTML tags
    .replace(/!\[[^\]]*\]\([^)]*\)/g, ' ')        // images / badges
    .replace(/\[([^\]]*)\]\([^)]*\)/g, '$1')      // [text](url) → text
    .replace(/\[([^\]]+)\]\[[^\]]*\]/g, '$1');    // [text][ref] → text

  const paragraphs = t
    .split(/\n\s*\n/)
    .map((p) =>
      p
        .split('\n')
        .filter((line) => {
          const l = line.trim();
          return l && !/^#{1,6}\s/.test(l) && !/^[|=\-_*]{3,}$/.test(l) && !/^\|/.test(l) && !/^\[[^\]]+\]:\s/.test(l);
        })
        .join(' ')
        .replace(/[*_`>#]+/g, '')                 // leftover markdown markers
        .replace(/\s+/g, ' ')
        .trim()
    )
    .filter((p) => p.length >= 40 && p.split(' ').length >= 6); // skip nav lines / one-word fragments

  if (paragraphs.length === 0) return '';

  let summary = paragraphs[0];
  for (let i = 1; i < paragraphs.length && summary.length < maxLen * 0.6; i++) {
    summary += ' ' + paragraphs[i];
  }
  if (summary.length > maxLen) {
    summary = summary.slice(0, maxLen - 1);
    summary = summary.replace(/\s+\S*$/, '').trimEnd() + '…'; // cut on a word boundary
  }
  return summary;
}

// ── 3. Build the Telegram message (parse_mode = HTML) ────────────────────────
const esc = (s) =>
  String(s === null || s === undefined ? '' : s)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');

const fmt = (n) => Number(n).toLocaleString('en-US');
const clip = (s, max) => (s.length > max ? s.slice(0, max - 1).trimEnd() + '…' : s);

function buildMessage(descMax, readmeMax) {
  let dateLabel;
  try {
    dateLabel = $now.toFormat('dd LLL yyyy, HH:mm');
  } catch (e) {
    dateLabel = new Date().toISOString().slice(0, 16).replace('T', ' ') + ' UTC';
  }

  const lines = [];
  lines.push('📰 <b>GitHub Daily Brief</b>');
  lines.push('Topic: ' + esc(data.topic) + ' · ' + esc(dateLabel));
  lines.push('');
  lines.push('🏆 <b>Top ' + data.topRepos.length + ' repositories by stars</b>');

  for (const r of data.topRepos) {
    lines.push('');
    lines.push('<b>' + r.rank + '. ' + esc(r.fullName) + '</b>');
    lines.push('⭐ ' + fmt(r.stars) + '  ·  💻 ' + esc(r.language));
    lines.push(esc(clip(r.description, descMax)));
    lines.push('🔗 ' + esc(r.url));
  }

  lines.push('');
  lines.push('📖 <b>README summary — ' + esc(data.topRepo.fullName) + '</b>');
  if (readme.available && readme.summary) {
    lines.push(esc(clip(readme.summary, readmeMax)));
  } else {
    lines.push('<i>' + esc(readme.note || 'README summary not available.') + '</i>');
  }
  return lines.join('\n');
}

// Try normal sizes first, then progressively shorter if Telegram's limit would be exceeded.
let telegramText = buildMessage(140, README_SUMMARY_MAX);
if (telegramText.length > TELEGRAM_LIMIT) telegramText = buildMessage(80, 220);
if (telegramText.length > TELEGRAM_LIMIT) telegramText = buildMessage(50, 120);

// ── 4. Output ────────────────────────────────────────────────────────────────
return [
  {
    json: {
      generatedAt: data.generatedAt,
      topic: data.topic,
      topRepo: data.topRepo,       // IF node checks topRepo.stars
      topRepos: data.topRepos,
      readme,
      telegramText,
      telegramTextLength: telegramText.length,
    },
  },
];

// ─────────────────────────────────────────────────────────────────────────────
// Node:  Log Fallback
// Type:  Code (JavaScript) — Mode: "Run Once for All Items"
// Runs on the FALSE branch of "Stars > 1000?" (top repository has 1,000 stars or fewer).
// No Telegram notification is sent; instead a structured log entry is written to the
// n8n server console AND returned as the node output so it is visible in the
// execution view (useful as a screenshot for the assessment).
// ─────────────────────────────────────────────────────────────────────────────

const THRESHOLD = 1000; // must match the IF node's right-hand value

const input = $input.first().json;
const top = input.topRepo || {};

const entry = {
  level: 'INFO',
  event: 'digest_suppressed_below_threshold',
  message:
    'Top repository "' + (top.fullName || 'unknown') + '" has ' + (top.stars ?? 'unknown') +
    ' stars, which is not more than ' + THRESHOLD + '. No Telegram digest was sent.',
  threshold: THRESHOLD,
  topRepo: {
    fullName: top.fullName || null,
    stars: top.stars ?? null,
    language: top.language || null,
    url: top.url || null,
  },
  readmeStatus: input.readme ? input.readme.status : 'unknown',
  checkedAt: new Date().toISOString(),
};

console.log('[GitHub Daily Brief] ' + JSON.stringify(entry));

return [{ json: entry }];

// ─────────────────────────────────────────────────────────────────────────────
// Node:  Format Error
// Type:  Code (JavaScript) — Mode: "Run Once for All Items"
// Receives items from the ERROR outputs of:
//   • Search GitHub Repos   • Transform Repos   • Build Digest   • Send Daily Digest
// and turns them into a clear, secret-free message for "Send Error Alert".
// ─────────────────────────────────────────────────────────────────────────────

// Which node did this error come from? ($prevNode is provided by n8n.)
const stage =
  typeof $prevNode !== 'undefined' && $prevNode && $prevNode.name ? $prevNode.name : 'unknown node';

// Never leak a Telegram bot token if it ever shows up inside an error string.
const redact = (s) => String(s).replace(/bot\d{6,}:[A-Za-z0-9_-]{20,}/g, 'bot<redacted>');

function extract(raw) {
  const e = raw && raw.error !== undefined ? raw.error : raw;
  if (typeof e === 'string') return { message: e };
  if (e && typeof e === 'object') {
    return {
      message: e.message || e.description || 'Unknown error',
      description: e.description && e.description !== e.message ? e.description : '',
      status: e.httpCode || e.statusCode || e.status || (e.cause && (e.cause.status || e.cause.statusCode)) || null,
      code: e.code || (e.cause && e.cause.code) || null,
    };
  }
  return { message: 'Unknown error (no error details were provided).' };
}

function hint(stageName, status, message) {
  const m = String(message).toLowerCase();
  const st = Number(status);
  // The Telegram nodes are named "Send Daily Digest" / "Send Error Alert" (no "telegram" in the name).
  const isTelegram = /^Send (Daily Digest|Error Alert)$/.test(stageName) || /telegram|chat not found/i.test(m);

  if (isTelegram) {
    if (m.includes('chat not found')) return 'Chat ID is wrong, or you have not sent /start to the bot yet.';
    if (st === 401 || m.includes('unauthorized')) return 'Telegram bot token is invalid or revoked. Re-create the Telegram credential in n8n.';
    if (st === 400) return 'Telegram rejected the request (bad chat ID or message formatting).';
    return 'Check the Telegram credential and Chat ID on the Telegram node.';
  }
  if (st === 429 || (st === 403 && (m.includes('rate limit') || m.includes('forbidden') || m.includes('too many')))) {
    return 'GitHub API rate limit probably reached (unauthenticated search = 10 requests/min). Wait a minute, or add a GitHub token (see README).';
  }
  if (st === 401) return 'GitHub rejected the credentials. Remove or fix the Authorization header.';
  if (st === 404) return 'GitHub endpoint or resource not found. Check the request URL.';
  if (st === 422) return 'GitHub rejected the search query. Check the `q` parameter.';
  if (st >= 500) return 'GitHub API is having problems. It is safe to retry later.';
  if (/enotfound|econnrefused|econnreset|etimedout|timeout|timed out|getaddrinfo/.test(m)) {
    return 'Network problem reaching the API (DNS / connection / timeout). Check connectivity from the n8n host.';
  }
  if (m.includes('returned 0 repositories') || m.includes('no "items"')) {
    return 'The search query returned no usable data. Check the topic in the `q` parameter.';
  }
  return 'Open the failed execution in n8n and inspect the node named above.';
}

let executionId = 'n/a';
try {
  executionId = $execution.id || 'n/a';
} catch (e) {
  /* $execution not available — ignore */
}

const out = $input.all().map((item) => {
  const d = extract(item.json);
  const status = d.status || (String(d.message).match(/\b([45]\d{2})\b/) || [])[1] || null;
  const message = redact(d.message);
  const timestamp = new Date().toISOString();
  const tip = hint(stage, status, message);

  const lines = [
    '⚠️ GitHub Daily Brief FAILED',
    'Stage: ' + stage,
    'Error: ' + message.slice(0, 600),
  ];
  if (status) lines.push('HTTP status: ' + status);
  if (d.code) lines.push('Code: ' + d.code);
  if (d.description) lines.push('Details: ' + redact(d.description).slice(0, 300));
  lines.push('Hint: ' + tip);
  lines.push('Execution ID: ' + executionId);
  lines.push('Time (UTC): ' + timestamp);

  const telegramText = lines.join('\n');
  console.error('[GitHub Daily Brief] ' + telegramText.replace(/\n/g, ' | '));

  return {
    json: { stage, errorMessage: message, httpStatus: status, code: d.code || null, hint: tip, executionId, timestamp, telegramText },
  };
});

return out;
